<h2>Calculate photo print size from pixels</h2><p class="lead">Convert image pixel dimensions into maximum print dimensions at a chosen PPI and check a custom print size.</p><div class="notice">Adobe distinguishes image resolution in PPI from printer resolution in DPI. The best PPI depends on printer, viewing distance, sharpening and the print provider’s workflow.</div><div class="form-grid"><div class="field"><label for="pxw">Image width (pixels)</label><input id="pxw" type="number" value="6000" min="1" step="1"></div><div class="field"><label for="pxh">Image height (pixels)</label><input id="pxh" type="number" value="4000" min="1" step="1"></div><div class="field"><label for="ppi">Target print resolution (PPI)</label><input id="ppi" type="number" value="300" min="1" step="any"></div><div class="field"><label for="pw">Optional desired print width (inches)</label><input id="pw" type="number" value="20" min="0.01" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Print size at target PPI</span><strong id="max">—</strong></div><div class="metric"><span>Effective PPI at desired width</span><strong id="effective">—</strong></div><div class="metric"><span>Height at desired width</span><strong id="height">—</strong></div><div class="metric"><span>Image megapixels</span><strong id="mp">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('max').textContent='—';$('effective').textContent='—';$('height').textContent='—';$('mp').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const w=num('pxw'),h=num('pxh'),ppi=num('ppi'),pw=num('pw');if(!(w>0&&h>0&&ppi>0&&pw>0))throw 0;const wi=w/ppi,hi=h/ppi,ph=pw*h/w,eff=w/pw;$('max').textContent=fmt(wi,2)+' × '+fmt(hi,2)+' in';$('effective').textContent=fmt(eff,0)+' PPI';$('height').textContent=fmt(ph,2)+' in';$('mp').textContent=fmt(w*h/1e6,2)+' MP';$('note').textContent='PPI describes image pixels per printed inch. Printer DPI is a different device specification; confirm the image-resolution requirement with your lab or print provider.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
